from collections import Counter
class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        a = list(nums2)
        res = []
        for q in queries:
            if q[0] == 1:
                _, x, y, val = q
                for i in range(x, y + 1):
                    a[i] += val
            else:
                c = Counter(a)
                res.append(sum(c.get(q[1] - v, 0) for v in nums1))
        return res

