import math
from collections import Counter
class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums2)
        B = max(1, math.isqrt(n))
        nb = (n + B - 1) // B
        cur = list(nums2)
        cnt = [Counter() for _ in range(nb)]
        for i, v in enumerate(cur):
            cnt[i // B][v] += 1
        lazy = [0] * nb
        res = []
        def upd(i, val):
            b = i // B
            c = cnt[b]
            old = cur[i] + lazy[b]
            c[old] -= 1
            if not c[old]:
                del c[old]
            cur[i] += val
            c[cur[i] + lazy[b]] += 1
        for q in queries:
            if q[0] == 1:
                _, x, y, val = q
                bx, by = x // B, y // B
                if bx == by:
                    for i in range(x, y + 1):
                        upd(i, val)
                else:
                    for i in range(x, (bx + 1) * B):
                        upd(i, val)
                    for b in range(bx + 1, by):
                        lazy[b] += val
                    for i in range(by * B, y + 1):
                        upd(i, val)
            else:
                tot = q[1]
                s = 0
                for v in nums1:
                    t = tot - v
                    for b in range(nb):
                        s += cnt[b].get(t - lazy[b], 0)
                res.append(s)
        return res

