class Solution {
public:
    vector<long long> numberOfPairs(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
        int n = nums2.size();
        int B = max(1, (int)sqrt((double)n));
        int nb = (n + B - 1) / B;
        vector<long long> cur(nums2.begin(), nums2.end());
        vector<unordered_map<long long,long long>> cnt(nb);
        for (int i = 0; i < n; i++) cnt[i / B][cur[i]]++;
        vector<long long> lazy(nb, 0);
        vector<long long> res;
        auto upd = [&](int i, long long val) {
            int b = i / B;
            auto& c = cnt[b];
            long long old = cur[i] + lazy[b];
            if (--c[old] == 0) c.erase(old);
            cur[i] += val;
            c[cur[i] + lazy[b]]++;
        };
        for (auto& q : queries) {
            if (q[0] == 1) {
                int x = q[1], y = q[2]; long long val = q[3];
                int bx = x / B, by = y / B;
                if (bx == by) { for (int i = x; i <= y; i++) upd(i, val); }
                else {
                    for (int i = x; i < (bx + 1) * B; i++) upd(i, val);
                    for (int b = bx + 1; b < by; b++) lazy[b] += val;
                    for (int i = by * B; i <= y; i++) upd(i, val);
                }
            } else {
                long long tot = q[1], s = 0;
                for (int v : nums1) {
                    long long t = tot - v;
                    for (int b = 0; b < nb; b++) {
                        auto it = cnt[b].find(t - lazy[b]);
                        if (it != cnt[b].end()) s += it->second;
                    }
                }
                res.push_back(s);
            }
        }
        return res;
    }
};

