class Solution {
    public long[] numberOfPairs(int[] nums1, int[] nums2, int[][] queries) {
        int n = nums2.length;
        int B = Math.max(1, (int) Math.sqrt(n));
        int nb = (n + B - 1) / B;
        long[] cur = new long[n];
        for (int i = 0; i < n; i++) cur[i] = nums2[i];
        List<HashMap<Long, Long>> cnt = new ArrayList<>();
        for (int b = 0; b < nb; b++) cnt.add(new HashMap<>());
        for (int i = 0; i < n; i++) cnt.get(i / B).merge(cur[i], 1L, Long::sum);
        long[] lazy = new long[nb];
        int m = 0;
        for (int[] q : queries) if (q[0] == 2) m++;
        long[] res = new long[m];
        int idx = 0;
        for (int[] q : queries) {
            if (q[0] == 1) {
                int x = q[1], y = q[2]; long val = q[3];
                int bx = x / B, by = y / B;
                if (bx == by) {
                    for (int i = x; i <= y; i++) upd(cnt, lazy, cur, B, i, val);
                } else {
                    for (int i = x; i < (bx + 1) * B; i++) upd(cnt, lazy, cur, B, i, val);
                    for (int b = bx + 1; b < by; b++) lazy[b] += val;
                    for (int i = by * B; i <= y; i++) upd(cnt, lazy, cur, B, i, val);
                }
            } else {
                long tot = q[1], s = 0;
                for (int v : nums1) {
                    long t = tot - v;
                    for (int b = 0; b < nb; b++) {
                        Long c = cnt.get(b).get(t - lazy[b]);
                        if (c != null) s += c;
                    }
                }
                res[idx++] = s;
            }
        }
        return res;
    }
    private void upd(List<HashMap<Long, Long>> cnt, long[] lazy, long[] cur, int B, int i, long val) {
        int b = i / B;
        HashMap<Long, Long> c = cnt.get(b);
        long old = cur[i] + lazy[b];
        long nc = c.get(old) - 1;
        if (nc == 0) c.remove(old); else c.put(old, nc);
        cur[i] += val;
        c.merge(cur[i] + lazy[b], 1L, Long::sum);
    }
}

