var numberOfPairs = function(nums1, nums2, queries) {
    const n = nums2.length;
    const B = Math.max(1, Math.floor(Math.sqrt(n)));
    const nb = Math.ceil(n / B);
    const cur = [...nums2];
    const cnt = Array.from({length: nb}, () => new Map());
    for (let i = 0; i < n; i++) {
        const c = cnt[Math.floor(i / B)];
        c.set(cur[i], (c.get(cur[i]) || 0) + 1);
    }
    const lazy = new Array(nb).fill(0);
    const res = [];
    const upd = (i, val) => {
        const b = Math.floor(i / B), c = cnt[b];
        const old = cur[i] + lazy[b];
        const nc = c.get(old) - 1;
        if (nc === 0) c.delete(old); else c.set(old, nc);
        cur[i] += val;
        const nw = cur[i] + lazy[b];
        c.set(nw, (c.get(nw) || 0) + 1);
    };
    for (const q of queries) {
        if (q[0] === 1) {
            const x = q[1], y = q[2], val = q[3];
            const bx = Math.floor(x / B), by = Math.floor(y / B);
            if (bx === by) {
                for (let i = x; i <= y; i++) upd(i, val);
            } else {
                for (let i = x; i < (bx + 1) * B; i++) upd(i, val);
                for (let b = bx + 1; b < by; b++) lazy[b] += val;
                for (let i = by * B; i <= y; i++) upd(i, val);
            }
        } else {
            const tot = q[1];
            let s = 0;
            for (const v of nums1) {
                const t = tot - v;
                for (let b = 0; b < nb; b++) {
                    s += cnt[b].get(t - lazy[b]) || 0;
                }
            }
            res.push(s);
        }
    }
    return res;
};
